let texteComplet = $input.item.json.text; 

let morceaux = texteComplet.split("[INTERNAL_MESSAGE]");

let reponseClient = morceaux[0].replace("[CUSTOMER_REPLY]", "").trim();

let messageInterne = morceaux[1] ? morceaux[1].trim() : "No internal message generated.";

return {
  json: {
    Client: reponseClient,
    Intern: messageInterne
  }
};

